{"content": "import torch
import torch.nn as nn
import tilelang
import tilelang.language as T

EPS = 1e-6


@tilelang.jit
def topk_kernel(x_2d, output_2d, k, dim_size, batch_size, largest):
    with T.Kernel(batch_size, is_npu=True) as (cid, vid):
        x_ub = T.alloc_ub((dim_size,), x_2d.dtype)
        current_ub = T.alloc_ub((dim_size,), x_2d.dtype)
        next_ub = T.alloc_ub((dim_size,), x_2d.dtype)
        result = T.alloc_ub((k,), x_2d.dtype)

        T.copy(x_2d[cid, :], x_ub)
        T.copy(x_ub, current_ub)

        for i in range(k):
            if largest:
                max_val = T.reduce_max(current_ub)
            else:
                max_val = T.reduce_min(current_ub)
            result[i] = max_val

            diff = current_ub - max_val
            abs_diff = T.abs(diff)
            mask = 1.0 - T.min(abs_diff / EPS, 1.0)

            if largest:
                next_ub = current_ub * mask + (-1e30) * (1.0 - mask)
            else:
                next_ub = current_ub * mask + (1e30) * (1.0 - mask)

            T.copy(next_ub, current_ub)

        T.copy(result, output_2d[cid, :])


class ModelNew(nn.Module):
    def forward(self, x, k, dim=-1, largest=True, sorted=True):
        if dim < 0:
            dim = len(x.shape) + dim

        batch_size = 1
        for i, s in enumerate(x.shape):
            if i != dim:
                batch_size *= s
        dim_size = x.shape[dim]

        k = min(k, dim_size)

        x_2d = x.reshape(batch_size, dim_size)
        output_2d = torch.empty(batch_size, k, dtype=x.dtype, device=x.device)

        topk_kernel(x_2d, output_2d, k, dim_size, batch_size, largest)

        output_shape = list(x.shape)
        output_shape[dim] = k
        return output_2d.reshape(output_shape)
