19	namespace ascend_kernel {
20	
21	constexpr int64_t UB_SORT_CAPACITY = 2048;
22	constexpr int64_t MULTI_CORE_PER_LOOP = 512;
23	constexpr int64_t ONE_LOOP_MAX = 256;
24	
25	static void computeTiling(SortKernelTiling* t, int32_t totalLength)
26	{
27	    *t = SortKernelTiling{};
28	    t->totalLength = totalLength;
29	
30	    int64_t aligned = ((int64_t)totalLength * 4 + 31) / 32 * 32 / 4;
31	    int64_t sortNum = ((aligned + 31) / 32) * 32;
32	    t->sortNum = static_cast<int32_t>(sortNum);
33	
34	    if (totalLength <= (int32_t)UB_SORT_CAPACITY) {
35	        t->tilingMode = SORT_TILING_MODE_FULLLOAD;
36	        t->coreNum = 1;
37	        t->needCoreNum = 1;
38	        return;
39	    }
40	
41	    if (totalLength <= (int32_t)(UB_SORT_CAPACITY * 2)) {
42	        t->tilingMode = SORT_TILING_MODE_SINGLECORE;
43	        t->coreNum = 1;
44	        t->needCoreNum = 1;
45	        return;
46	    }
47	
48	    t->tilingMode = SORT_TILING_MODE_MULTICORE;
49	
50	    int32_t perLoop = static_cast<int32_t>(MULTI_CORE_PER_LOOP);
51	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
52	    auto totalCoreNum = static_cast<int32_t>(ascendcPlatform->GetCoreNum());
53	    int32_t needCores = std::min<int32_t>(totalCoreNum, (totalLength + perLoop - 1) / perLoop);
54	    if (needCores < 2) needCores = 2;
55	
56	    t->coreNum = needCores;
57	    t->needCoreNum = needCores;
58	
59	    int32_t perCore = (totalLength + needCores - 1) / needCores;
60	    perCore = ((perCore + 31) / 32) * 32;
61	    int32_t lastCore = totalLength - perCore * (needCores - 1);
62	    if (lastCore <= 0) {
63	        perCore = totalLength / needCores;
64	        perCore = ((perCore + 31) / 32) * 32;
65	        lastCore = totalLength - perCore * (needCores - 1);
66	    }
67	
68	    t->perCoreElements = perCore;
69	    t->lastCoreElements = lastCore;
70	
71	    int32_t loopElem = std::min<int32_t>(perLoop, perCore);
72	    loopElem = ((loopElem + 31) / 32) * 32;
73	
74	    t->perCorePerLoopElements = loopElem;
75	    t->perCoreLoops = (perCore + loopElem - 1) / loopElem;
76	    t->perCoreLastLoopElements = perCore - loopElem * (t->perCoreLoops - 1);
77	
78	    t->lastCorePerLoopElements = loopElem;
79	    t->lastCoreLoops = (lastCore + loopElem - 1) / loopElem;
80	    t->lastCoreLastLoopElements = lastCore - loopElem * (t->lastCoreLoops - 1);
81	
82	    t->oneLoopMaxElements = static_cast<int32_t>(ONE_LOOP_MAX);
83	}
84	
85	std::tuple<at::Tensor, at::Tensor> kv_sort(const at::Tensor& keys, const at::Tensor& values)
86	{
87	    TORCH_CHECK(keys.dim() == 1, "keys must be 1D");
88	    TORCH_CHECK(values.dim() == 1, "values must be 1D");
89	    TORCH_CHECK(keys.size(0) == values.size(0), "keys and values must have same length");
90	    TORCH_CHECK(keys.scalar_type() == at::kInt, "keys must be int32");
91	    TORCH_CHECK(values.scalar_type() == at::kInt, "values must be int32");
92	    TORCH_CHECK(keys.is_contiguous() && values.is_contiguous(), "inputs must be contiguous");
93	
94	    int32_t totalLength = static_cast<int32_t>(keys.size(0));
95	
96	    at::Tensor sortedKeys = at::empty_like(keys);
97	    at::Tensor sortedValues = at::empty_like(values);
98	
99	    at::Tensor tilingCpu = at::empty(
100	        {static_cast<int64_t>(sizeof(SortKernelTiling))},
101	        at::device(at::kCPU).dtype(at::kByte));
102	    auto* tiling = reinterpret_cast<SortKernelTiling*>(tilingCpu.data_ptr());
103	    computeTiling(tiling, totalLength);
104	
105	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
106	
107	    int64_t wsBytes = 0;
108	    if (tiling->tilingMode == SORT_TILING_MODE_MULTICORE) {
109	        int64_t perCoreSortLen = static_cast<int64_t>(tiling->perCoreElements) * 2;
110	        int64_t oneBufFloats = static_cast<int64_t>(tiling->needCoreNum) * perCoreSortLen;
111	        wsBytes = oneBufFloats * sizeof(float) * 2 + 4096;
112	    }
113	    at::Tensor workspace = at::empty({wsBytes}, keys.options().dtype(at::kByte));
114	
115	    uint32_t blockDim = static_cast<uint32_t>(tiling->coreNum);
116	    EXEC_KERNEL_CMD(kv_sort, blockDim, keys, values, sortedKeys, sortedValues, workspace, tilingNpu);
117	
118	    return std::make_tuple(sortedKeys, sortedValues);
119	}
120	
121	}  // namespace ascend_kernel
