39	__aicore__ inline int64_t AlignUp(int64_t elementNum, int64_t bytes)
40	{
41	    if (bytes == 0) return 0;
42	    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES / bytes;
43	}
44	
45	__aicore__ inline int64_t AlignUpBytes(int64_t elementNum, int64_t bytes)
46	{
47	    return (elementNum * bytes + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES;
48	}
