#include <algorithm>
#include <cstring>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_topk.h"
#include "topk_tiling.h"

namespace ascend_kernel {

constexpr int64_t UB_SORT_BYTES_PER_ELEMLLA = 24;  // approx bytes per element for Sort UB

at::Tensor topk(const at::Tensor& x, int64_t k, int64_t dim, bool largest, bool sorted)
{
    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
    TORCH_CHECK(dim >= 0 && dim < x.dim(), "dim out of range");
    TORCH_CHECK(k >= 1, "k must be >= 1");

    // Normalize dim (negative dim handling)
    if (dim < 0) dim += x.dim();

    // Compute batch_size and dim_size
    int64_t batch_size = 1;
    for (int64_t i = 0; i < x.dim(); i++) {
        if (i != dim) batch_size *= x.size(i);
    }
    int64_t dim_size = x.size(dim);
    int64_t clampedK = std::min(k, dim_size);

    // Reshape to 2D: (batch_size, dim_size)
    auto x2d = x.reshape({batch_size, dim_size});

    // Convert to float32 for Sort API
    auto xFloat = x2d.to(at::kFloat);
    if (!largest) {
        xFloat = xFloat.neg();
    }

    // Get UB size from platform
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t ubSize = ascendcPlatform->GetCoreMemSize(1);  // UB size in bytes

    // Compute chunk size based on UB capacity
    // Each chunk needs: copyIn(4) + idx(4) + temp(8) + sorted(8) + copyOut(4) = ~28 bytes/elem
    int64_t bytesPerElem = 28;
    int64_t maxChunkSize = ubSize / bytesPerElem;
    // Align to 32 elements for Sort API
    maxChunkSize = (maxChunkSize / 32) * 32;
    if (maxChunkSize < 32) maxChunkSize = 32;

    int64_t chunkSize = std::min(maxChunkSize, dim_size);
    chunkSize = ((chunkSize + 31) / 32) * 32;  // align to 32
    if (chunkSize > dim_size) chunkSize = dim_size;

    int64_t numChunks = (dim_size + chunkSize - 1) / chunkSize;
    int64_t totalBlocks = batch_size * numChunks;

    // Flatten for kernel
    auto xFlat = xFloat.reshape({-1});
    auto outputFlat = at::empty_like(xFlat);

    // Tiling
    TopKTiling tiling;
    tiling.dimSize = static_cast<int32_t>(dim_size);
    tiling.k = static_cast<int32_t>(clampedK);
    tiling.batchSize = static_cast<int32_t>(batch_size);
    tiling.chunkSize = static_cast<int32_t>(chunkSize);
    tiling.numChunks = static_cast<int32_t>(numChunks);

    auto tilingCpu = at::empty({static_cast<int64_t>(sizeof(TopKTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCpu.data_ptr(), &tiling, sizeof(TopKTiling));
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Launch kernel
    uint32_t blockDim = static_cast<uint32_t>(totalBlocks);
    EXEC_KERNEL_CMD(topk, blockDim, xFlat, outputFlat, tilingNpu);

    // Per-batch merge: combine sorted chunks within each batch
    auto output2d = outputFlat.reshape({batch_size, dim_size});
    auto result = at::empty_like(output2d);

    for (int64_t b = 0; b < batch_size; b++) {
        auto batchFlat = output2d[b].reshape({-1});
        // Sort all elements in this batch (descending)
        auto sorted = torch::sort(batchFlat, true);
        auto topKValues = sorted.values();
        if (!largest) {
            topKValues = topKValues.neg();
        }
        result[b].slice(0, 0, clampedK).copy_(topKValues.slice(0, 0, clampedK));
    }

    // Reshape to original shape with dim replaced by k
    std::vector<int64_t> outputShape(x.shape());
    outputShape[dim] = clampedK;
    return result.reshape(outputShape);
}

}  // namespace ascend_kernel
