#include "aclrtlaunch_topk.h"
#include "topk_tiling.h"

namespace ascend_kernel {

at::Tensor topk(const at::Tensor& x, int64_t k, int64_t dim, bool largest, bool sorted)
{
    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
    TORCH_CHECK(dim >= 0 && dim < x.dim(), "dim out of range");
    TORCH_CHECK(k >= 1, "k must be >= 1");

    if (dim < 0) dim += x.dim();

    // Compute permutation to move dim to the last position
    std::vector<int64_t> perm;
    for (int64_t i = 0; i < dim; i++) perm.push_back(i);
    for (int64_t i = dim + 1; i < x.dim(); i++) perm.push_back(i);
    perm.push_back(dim);

    std::vector<int64_t> inv_perm(x.dim());
    for (int64_t i = 0; i < x.dim(); i++) {
        inv_perm[perm[i]] = i;
    }

    // Permute x so target dim is last
    auto xPerm = x.permute(perm);

    int64_t dim_size = xPerm.size(xPerm.dim() - 1);
    int64_t batch_size = 1;
    for (int64_t i = 0; i < xPerm.dim() - 1; i++) {
        batch_size *= xPerm.size(i);
    }
    int64_t clampedK = std::min(k, dim_size);

    // Convert to float32 for Sort API
    auto xFloat = xPerm.to(at::kFloat);
    if (!largest) {
        xFloat = xFloat.neg();
    }

    // Get UB size
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Compute chunk size
    int64_t bytesPerElem = 28;
    int64_t maxChunkSize = ubSize / bytesPerElem;
    maxChunkSize = (maxChunkSize / 32) * 32;
    if (maxChunkSize < 32) maxChunkSize = 32;

