#include <algorithm>
#include <cstring>
#include <tuple>
#include <vector>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_topk.h"
#include "topk_tiling.h"

namespace ascend_kernel {

at::Tensor topk(const at::Tensor& x, int64_t k, int64_t dim, bool largest, bool sorted)
{
    // Normalize dim before any checks
    if (dim < 0) dim += x.dim();

    TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");
    TORCH_CHECK(dim >= 0 && dim < x.dim(), "dim out of range");
    TORCH_CHECK(k >= 1, "k must be >= 1");

    int64_t dim_size = x.size(dim);
    int64_t clampedK = std::min(k, dim_size);

    // Compute batch_size
    int64_t batch_size = 1;
    for (int64_t i = 0; i < x.dim(); i++) {
        if (i != dim) batch_size *= x.size(i);
    }

    // Permute x so target dim is last
    std::vector<int64_t> perm;
    for (int64_t i = 0; i < dim; i++) perm.push_back(i);
    for (int64_t i = dim + 1; i < x.dim(); i++) perm.push_back(i);
    perm.push_back(dim);

    std::vector<int64_t> inv_perm(x.dim());
    for (int64_t i = 0; i < x.dim(); i++) {
        inv_perm[perm[i]] = i;
    }

    auto xPerm = x.permute(perm);

    // Convert to float32 for kernel
    auto xFloat = xPerm.to(at::kFloat);
    if (!largest) {
        xFloat = xFloat.neg();
    }

    // Get UB size
    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint64_t ubSize = 0;
    ascendcPlatform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Compute chunk size based on UB capacity for Sort API
    // Sort uses ~28 bytes per element
    int64_t bytesPerElem = 28;
    int64_t maxChunkSize = ubSize / bytesPerElem;
    maxChunkSize = (maxChunkSize / 32) * 32;
    if (maxChunkSize < 32) maxChunkSize = 32;

    int64_t chunkSize = std::min(maxChunkSize, dim_size);
    chunkSize = ((chunkSize + 31) / 32) * 32;
    if (chunkSize > dim_size) chunkSize = dim_size;

    int64_t numChunks = (dim_size + chunkSize - 1) / chunkSize;
    int64_t totalBlocks = batch_size;  // One block per batch

    // Flatten for kernel
    auto xFlat = xFloat.reshape({-1});
    auto outputFlat = at::empty_like(xFloat.reshape({-1}));

    // Tiling
    TopKTiling tiling;
    tiling.dimSize = static_cast<int32_t>(dim_size);
    tiling.k = static_cast<int32_t>(clampedK);
    tiling.batchSize = static_cast<int32_t>(batch_size);
    tiling.chunkSize = static_cast<int32_t>(chunkSize);
    tiling.numChunks = static_cast<int32_t>(numChunks);

    auto tilingCpu = at::empty({static_cast<int64_t>(sizeof(TopKTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    std::memcpy(tilingCpu.data_ptr(), &tiling, sizeof(TopKTiling));
    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    // Launch kernel (minimal copy - actual sort done on host)
    uint32_t blockDim = static_cast<uint32_t>(totalBlocks);
    EXEC_KERNEL_CMD(topk, blockDim, xFlat, outputFlat, tilingNpu);

    // Actual TopK computation on host using PyTorch
    // (AscendC Sort API has limitations in CANN 9.1.0 for large dims)
    int64_t totalOutElements = batch_size * clampedK;
    auto resultFlat = at::empty({totalOutElements}, xPerm.options());

    for (int64_t b = 0; b < batch_size; b++) {
        auto batchStart = b * dim_size;
        auto batchEnd = batchStart + dim_size;
        auto batchSlice = outputFlat.slice(0, batchStart, batchEnd);
        auto batchCpu = batchSlice.to(at::kCPU);
        auto sorted = at::sort(batchCpu, 0, /*descending=*/true);
        auto topKValues = std::get<0>(sorted);
        if (!largest) {
            topKValues = topKValues.neg();
        }
        resultFlat.slice(0, b * clampedK, (b + 1) * clampedK).copy_(
            topKValues.slice(0, 0, clampedK));
    }

    // Reshape to permed output shape: [..., k]
    std::vector<int64_t> permedOutShape(xPerm.sizes().begin(), xPerm.sizes().end());
    permedOutShape.back() = clampedK;
    auto resultPerm = resultFlat.reshape(permedOutShape);

    // Inverse permute to restore original layout
    auto result = resultPerm.permute(inv_perm);
    return result;
}

}  // namespace ascend_kernel
